package com.berling.marketplace.utils\n\nimport android.content.Context\nimport kotlinx.serialization.Serializable\nimport kotlinx.serialization.encodeToString\nimport kotlinx.serialization.json.Json\nimport java.io.File\n\n/**\n * OfflineMessageCache handles offline storage and retrieval of messages\n * Allows users to view cached messages even without internet connection\n */\nobject OfflineMessageCache {\n\n    private const val MESSAGES_CACHE_DIR = \"offline_messages\"\n    private const val CONVERSATIONS_CACHE_FILE = \"conversations.json\"\n    \n    private val json = Json { ignoreUnknownKeys = true }\n\n    /**\n     * Get offline cache directory\n     */\n    private fun getCacheDir(context: Context): File {\n        val cacheDir = File(context.filesDir, MESSAGES_CACHE_DIR)\n        if (!cacheDir.exists()) {\n            cacheDir.mkdirs()\n        }\n        return cacheDir\n    }\n\n    /**\n     * Save message to offline cache\n     */\n    fun saveMessageOffline(\n        context: Context,\n        conversationId: String,\n        message: OfflineMessage\n    ): Boolean {\n        return try {\n            val cacheDir = getCacheDir(context)\n            val file = File(cacheDir, \"$conversationId.json\")\n            \n            val existingMessages = if (file.exists()) {\n                try {\n                    val content = file.readText()\n                    json.decodeFromString<List<OfflineMessage>>(content).toMutableList()\n                } catch (e: Exception) {\n                    mutableListOf()\n                }\n            } else {\n                mutableListOf()\n            }\n            \n            existingMessages.add(message)\n            file.writeText(json.encodeToString(existingMessages))\n            true\n        } catch (e: Exception) {\n            false\n        }\n    }\n\n    /**\n     * Get cached messages for a conversation\n     */\n    fun getCachedMessages(\n        context: Context,\n        conversationId: String\n    ): List<OfflineMessage> {\n        return try {\n            val cacheDir = getCacheDir(context)\n            val file = File(cacheDir, \"$conversationId.json\")\n            \n            if (file.exists()) {\n                val content = file.readText()\n                json.decodeFromString<List<OfflineMessage>>(content)\n            } else {\n                emptyList()\n            }\n        } catch (e: Exception) {\n            emptyList()\n        }\n    }\n\n    /**\n     * Save conversation to offline cache\n     */\n    fun saveConversationOffline(\n        context: Context,\n        conversation: OfflineConversation\n    ): Boolean {\n        return try {\n            val cacheDir = getCacheDir(context)\n            val file = File(cacheDir, CONVERSATIONS_CACHE_FILE)\n            \n            val existingConversations = if (file.exists()) {\n                try {\n                    val content = file.readText()\n                    json.decodeFromString<List<OfflineConversation>>(content).toMutableList()\n                } catch (e: Exception) {\n                    mutableListOf()\n                }\n            } else {\n                mutableListOf()\n            }\n            \n            // Remove if exists and re-add to update\n            existingConversations.removeAll { it.id == conversation.id }\n            existingConversations.add(0, conversation) // Add to top\n            \n            file.writeText(json.encodeToString(existingConversations))\n            true\n        } catch (e: Exception) {\n            false\n        }\n    }\n\n    /**\n     * Get all cached conversations\n     */\n    fun getCachedConversations(context: Context): List<OfflineConversation> {\n        return try {\n            val cacheDir = getCacheDir(context)\n            val file = File(cacheDir, CONVERSATIONS_CACHE_FILE)\n            \n            if (file.exists()) {\n                val content = file.readText()\n                json.decodeFromString<List<OfflineConversation>>(content)\n            } else {\n                emptyList()\n            }\n        } catch (e: Exception) {\n            emptyList()\n        }\n    }\n\n    /**\n     * Get specific cached conversation\n     */\n    fun getCachedConversation(\n        context: Context,\n        conversationId: String\n    ): OfflineConversation? {\n        return getCachedConversations(context).find { it.id == conversationId }\n    }\n\n    /**\n     * Clear cache for specific conversation\n     */\n    fun clearConversationCache(context: Context, conversationId: String): Boolean {\n        return try {\n            val cacheDir = getCacheDir(context)\n            val file = File(cacheDir, \"$conversationId.json\")\n            file.delete()\n        } catch (e: Exception) {\n            false\n        }\n    }\n\n    /**\n     * Clear all offline cache\n     */\n    fun clearAllCache(context: Context): Boolean {\n        return try {\n            val cacheDir = getCacheDir(context)\n            cacheDir.deleteRecursively()\n        } catch (e: Exception) {\n            false\n        }\n    }\n\n    /**\n     * Get cache size in bytes\n     */\n    fun getCacheSize(context: Context): Long {\n        return try {\n            val cacheDir = getCacheDir(context)\n            cacheDir.walkTopDown().map { it.length() }.sum()\n        } catch (e: Exception) {\n            0\n        }\n    }\n\n    /**\n     * Check if has cached messages for conversation\n     */\n    fun hasCachedMessages(context: Context, conversationId: String): Boolean {\n        return try {\n            val cacheDir = getCacheDir(context)\n            val file = File(cacheDir, \"$conversationId.json\")\n            file.exists()\n        } catch (e: Exception) {\n            false\n        }\n    }\n}\n\n@Serializable\ndata class OfflineMessage(\n    val id: String,\n    val conversationId: String,\n    val senderId: String,\n    val senderName: String,\n    val receiverId: String,\n    val content: String,\n    val isRead: Boolean = false,\n    val timestamp: Long = System.currentTimeMillis(),\n    val isSynced: Boolean = false\n)\n\n@Serializable\ndata class OfflineConversation(\n    val id: String,\n    val participant1Id: String,\n    val participant1Name: String,\n    val participant1PhotoUrl: String,\n    val participant2Id: String,\n    val participant2Name: String,\n    val participant2PhotoUrl: String,\n    val productId: String? = null,\n    val productTitle: String? = null,\n    val productImageUrl: String? = null,\n    val lastMessage: String = \"\",\n    val lastMessageTime: Long = System.currentTimeMillis(),\n    val unreadCount: Int = 0,\n    val lastSyncTime: Long = 0\n)\n
